import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"韩奕","description":"","frontmatter":{"title":"韩奕","date":"2026-11-09T00:00:00.000Z","seq":27,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/韩奕.md","filePath":"blogs/诗经·大雅/韩奕.md"}'),o={name:"blogs/诗经·大雅/韩奕.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="韩奕" tabindex="-1">韩奕 <a class="header-anchor" href="#韩奕" aria-label="Permalink to &quot;韩奕&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">奕奕梁山，维禹甸之，有倬其道。</p><p class="poem-stanza">韩侯受命，王亲命之：缵戎祖考，无废朕命。</p><p class="poem-stanza">夙夜匪解，虔共尔位，朕命不易。</p><p class="poem-stanza">粲不庭方，以佐戎辟。四牡奕奕，孔修且张。</p><p class="poem-stanza">韩侯入觐，以其介圭，入觐于王。</p><p class="poem-stanza">王锡韩侯，淑旂绥章，簟茀错衡。</p><p class="poem-stanza">玄衮赤舄，钩膺镂锡，鞹鞃浅幭，鞗革金厄。</p><p class="poem-stanza">韩侯出祖，出宿于屠。显父饯之，清酒百壶。</p><p class="poem-stanza">其殽维何？炰鳖鲜鱼。其蔌维何？维笋及蒲。</p><p class="poem-stanza">其赠维何？乘马路车。笾豆有且。侯氏燕胥。</p><p class="poem-stanza">韩侯取妻，汾王之甥，蹶父之子。</p><p class="poem-stanza">韩侯迎止，于蹶之里。</p><p class="poem-stanza">百两彭彭，八鸾锵锵，不显其光。</p><p class="poem-stanza">诸娣从之，祁祁如云。韩侯顾之，烂其盈门。</p><p class="poem-stanza">蹶父孔武，靡国不到。为韩姞相攸，莫如韩乐。</p><p class="poem-stanza">孔乐韩土，川泽訏訏，鲂鱮甫甫，麀鹿噳噳。</p><p class="poem-stanza">有熊有罴，有猫有虎。庆既令居，韩姞燕誉。</p><p class="poem-stanza">溥彼韩城，燕师所完。以先祖受命，因时百蛮。</p><p class="poem-stanza">王锡韩侯，其追其貊。奄受北国，因以其伯。</p><p class="poem-stanza">实墉实壑，实亩实藉。献其貔皮，赤豹黄罴。</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
